const items = $input.all().map((i) => i.json);
const businesses = Array.isArray(items[0]) ? items[0] : items;

// Vencimientos Modelo 303 por trimestre (año del periodo)
function deadlinesFor(year) {
  return [
    { label: '1T', deadline: new Date(`${year}-04-20`) },
    { label: '2T', deadline: new Date(`${year}-07-20`) },
    { label: '3T', deadline: new Date(`${year}-10-20`) },
    { label: '4T', deadline: new Date(`${year + 1}-01-30`) }
  ];
}

const now = new Date();
const alerts = [];

for (const b of businesses) {
  if (!b || !b.id) continue;
  const cands = [...deadlinesFor(now.getFullYear()), ...deadlinesFor(now.getFullYear() + 1)]
    .filter((d) => d.deadline.getTime() >= now.getTime() - 86400000)
    .sort((a, z) => a.deadline - z.deadline);
  const next = cands[0];
  if (!next) continue;
  const days = Math.ceil((next.deadline - now) / 86400000);
  if (days <= 30) {
    alerts.push({
      json: {
        business_id: b.id,
        severity: days <= 7 ? 'high' : 'medium',
        type: 'PERIOD_DEADLINE',
        title: `Vence el Modelo 303 (${next.label}) en ${days} días`,
        description: `El plazo de presentación del Modelo 303 del trimestre ${next.label} termina el ${next.deadline.toISOString().split('T')[0]}. Revisa y concilia tus facturas pendientes.`,
        evidence: { quarter: next.label, deadline: next.deadline.toISOString().split('T')[0], daysRemaining: days },
        entity_type: 'period',
        entity_id: null,
        source: 'n8n',
        status: 'OPEN'
      }
    });
  }
}

return alerts;
